properties.query:
// PsExec unzips PSEXESVC.exe onto the target and starts it as a service. The
// binary name is near-unique to the tool, and legitimate software does not
// name its service binary PSEXESVC unless it *is* PsExec.
let psexec_service = dynamic(["psexesvc.exe"]);
// Children the service control manager spawns when a service image or command
// line points at an administrative share (the PsExec -c / -s pattern, and the
// same primitive used by SMB-based relay tooling).
let shell_binaries = dynamic([
  "cmd.exe", "powershell.exe", "pwsh.exe", "net.exe", "net1.exe",
  "whoami.exe", "sc.exe", "wmic.exe"
]);
let admin_share_marker = "ADMIN$";
DeviceProcessEvents
| where TimeGenerated > ago(1h)
| where InitiatingProcessFileName in~ (psexec_service)
      or (InitiatingProcessFileName =~ "services.exe"
          and ProcessCommandLine contains admin_share_marker)
| where InitiatingProcessFileName in~ (psexec_service)
      or FileName in~ (shell_binaries)
| project TimeGenerated, DeviceId, DeviceName, AccountName, FileName,
          ProcessCommandLine, FolderPath, SHA256,
          InitiatingProcessFileName, InitiatingProcessCommandLine,
          InitiatingProcessAccountName
